const cfg = $('Config').first().json;
const helpers = this.helpers;

// 1) session cookie from the login node (fallback: log in again from here)
let rsid = '';
{
  const _li = $('RetailOS Login').first(); const h = (_li && _li.json && _li.json.headers) || {};
  const sc = [].concat(h['set-cookie'] || h['Set-Cookie'] || []);
  const hit = sc.map(c => String(c).split(';')[0]).find(c => c.startsWith('rsid='));
  if (hit) rsid = hit.slice(5);
}
if (!rsid) {
  let res = null;
  try {
    res = await helpers.httpRequest({
      method: 'POST', url: cfg.retailosUrl + '/login',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ username: cfg.retailosUser, password: cfg.retailosPass, next: '/products' }).toString(),
      returnFullResponse: true, maxRedirects: 0,
    });
  } catch (e) { res = { headers: (e && e.response && e.response.headers) || (e && e.headers) || null }; }
  const sc = res && res.headers ? [].concat(res.headers['set-cookie'] || []) : [];
  const hit = sc.map(c => String(c).split(';')[0]).find(c => c.startsWith('rsid='));
  if (hit) rsid = hit.slice(5);
}
if (!rsid) throw new Error('RetailOS login failed - check user/password in the Config node (5 wrong tries lock the account)');

// progress notes for the /audit/live page (fire-and-forget; a failed note never breaks the flow)
let csrf = '';
const beat = async msg => { try { await helpers.httpRequest({ method: 'POST', url: cfg.retailosUrl + '/progress/note', headers: { 'Content-Type': 'application/x-www-form-urlencoded', Cookie: 'rsid=' + rsid }, body: new URLSearchParams({ msg, csrf }).toString() }); } catch (e) {} };

const unescape = s => String(s).replace(/&#34;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
function firstGtin(barcodes) {
  for (const raw of String(barcodes || '').split(',')) {
    const c = raw.trim();
    if (!/^\d{8}$|^\d{12}$|^\d{13}$|^\d{14}$/.test(c)) continue;
    const d = [...c].map(Number);
    const sum = d.slice(0, -1).reverse().reduce((a, v, i) => a + v * (i % 2 ? 1 : 3), 0);
    if ((10 - sum % 10) % 10 === d[d.length - 1]) return c;
  }
  return '';
}

// 2) walk every page of Settings > Product set-up, keep the products with no picture
const out = [];
const ROW = /class="pimg" data-pid="(\d+)" data-name="([^"]*)" data-url="([^"]*)"[^>]*>[\s\S]*?<div class="small mute">([^<]*)<[/]div>/g;
for (let page = 1; page <= 200; page++) {
  const html = String(await helpers.httpRequest({
    method: 'GET', url: cfg.retailosUrl + '/products?page=' + page,
    headers: { Cookie: 'rsid=' + rsid },
  }));
  if (page === 1) {
    if (/name="username"/.test(html)) throw new Error('RetailOS rejected the session (wrong login, locked account, or the user must change password first)');
    const c = html.match(/var csrf='([^']+)'/) || html.match(/name="csrf" value="([^"]+)"/);
    if (!c) throw new Error('Could not find the CSRF token on the /products page');
    csrf = c[1];
    await beat('Signed in to RetailOS - scanning the product pages...');
  }
  let rows = 0, m;
  ROW.lastIndex = 0;
  while ((m = ROW.exec(html))) {
    rows++;
    if (m[3]) continue; // data-url set = product already has a picture
    out.push({ json: {
      pid: m[1], name: unescape(m[2]), barcode: m[4].trim(), gtin: firstGtin(m[4]),
      csrf, rsid,
      retailosUrl: cfg.retailosUrl,
      warehouseUrl: cfg.warehouseUrl, warehouseUser: cfg.warehouseUser, warehousePass: cfg.warehousePass,
    } });
  }
  await beat('Scanning products page ' + page + ' - ' + out.length + ' without pictures so far');
  if (rows === 0) break;
}
await beat(out.length ? 'Scan done - ' + out.length + ' products need a picture, attaching one by one' : 'Scan done - every tracked product already has a picture');
if (!out.length) throw new Error('Every tracked product already has a picture - nothing to do');
return out;

// Looks for this product's picture on the warehouse site (productlist.php).
// The site sits behind a login so its markup could not be inspected beforehand:
// match the 3 spots marked ADJUST to the real page once (open the site, press F12).
const item = $input.first().json;
let imageUrl = null;

if (item.warehouseUser) {
  const helpers = this.helpers;
  try {
    // 1) sign in (ADJUST: login URL + form field names of the warehouse site)
    let login = null;
    try {
      login = await helpers.httpRequest({
        method: 'POST', url: item.warehouseUrl + '/login.php', // ADJUST
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ username: item.warehouseUser, password: item.warehousePass }).toString(), // ADJUST field names
        returnFullResponse: true, maxRedirects: 0,
      });
    } catch (e) { login = e && e.response ? e.response : { headers: {} }; }
    const cookie = [].concat((login.headers && login.headers['set-cookie']) || [])
      .map(c => String(c).split(';')[0]).join('; ');

    // 2) search by barcode, fall back to the product name (ADJUST: query parameter name)
    const q = encodeURIComponent(item.gtin || item.barcode || item.name);
    const html = String(await helpers.httpRequest({
      method: 'GET', url: item.warehouseUrl + '/productlist.php?keyword=' + q, // ADJUST
      headers: cookie ? { Cookie: cookie } : {},
    }));

    // 3) first product image in the results page (ADJUST: match the site's real <img> markup)
    const m = html.match(/<img[^>]+src=["']([^"']+\.(?:jpg|jpeg|png|webp))[^"']*["']/i);
    if (m && !/logo|icon|blank/i.test(m[1])) imageUrl = new URL(m[1], item.warehouseUrl + '/').href;
  } catch (e) {
    // warehouse unreachable: imageUrl stays null and the web branch takes over
  }
}
return [{ json: { ...item, imageUrl } }];

const ctx = $('Warehouse Find Image').first().json;
let imageUrl = null;
try {
  const p = $input.first().json;
  if (p && p.product) imageUrl = p.product.image_front_url || p.product.image_url || null;
} catch (e) {}
if (imageUrl && !String(imageUrl).startsWith('https://')) imageUrl = null;
try {
  await this.helpers.httpRequest({ method: 'POST', url: ctx.retailosUrl + '/progress/note',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Cookie: 'rsid=' + ctx.rsid },
    body: new URLSearchParams({ msg: '#' + ctx.pid + ' ' + ctx.name + ' - ' + (imageUrl ? 'found on the web, attaching...' : 'no picture found, skipping'), csrf: ctx.csrf }).toString() });
} catch (e) {}
return [{ json: { ...ctx, imageUrl } }];
